import{_ as a,o,c as t,a2 as i}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"ADR-0013 — Dettagli della Graph view (M6-WP1)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0013-graph-view-details.md","filePath":"adr/0013-graph-view-details.md"}'),n={name:"adr/0013-graph-view-details.md"};function r(d,e,l,s,c,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0013-—-dettagli-della-graph-view-m6-wp1" tabindex="-1">ADR-0013 — Dettagli della Graph view (M6-WP1) <a class="header-anchor" href="#adr-0013-—-dettagli-della-graph-view-m6-wp1" aria-label="Permalink to &quot;ADR-0013 — Dettagli della Graph view (M6-WP1)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §2.2.1, §2.5, §3.4.6, §4.2, Appendice A (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-24</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.5 <code>graph</code>; matrice funzioni (Graph view); D-06 (perimetro per-vault)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no (raffina: Canvas 2D invece di WebGL, ctime da frontmatter/mtime)</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>La roadmap M6-WP1 ammette <code>pixi.js</code> oppure canvas 2D. L&#39;indice (<code>index.db</code>) non memorizza il tempo di creazione dei file, necessario al timelapse.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ul><li><strong>Rendering Canvas 2D</strong>, senza <code>pixi.js</code>. Il layout (<code>d3-force</code> 3.0.0, pinnato) gira in un Web Worker; un solo <code>stroke</code> per gli archi e un <code>fill</code> per classe di colore. Misure in <code>docs/qa/m6-graph-benchmark.md</code>. Gli archi sono tracciati a 1 pixel di dispositivo (percorso &quot;hairline&quot; di Skia): linee più larghe su decine di migliaia di segmenti costano ~50 volte di più nei rasterizzatori CPU. Durante pan/zoom si trasforma un bitmap della scena (costo indipendente dalla dimensione del grafo) e si ridisegna esatto a gesto concluso.</li><li><strong>Tab del grafo come pseudo-path</strong> nel layout: <code>graph://global</code> e <code>graph://local/&lt;nota&gt;</code>; così la persistenza in <code>.memobrain/workspace.json</code> non cambia. All&#39;avvio i tab grafo non vengono scartati dal controllo di esistenza file.</li><li><strong>Dati</strong>: <code>GraphAPI.Build(vaultId, options)</code> esegue un numero fisso di query sull&#39;indice (file, link, tag, proprietà <code>created</code>, più la ricerca per query/gruppi) e restituisce nodi e archi indicizzati; oltre <code>maxNodes</code> (default 20000) restano i nodi più connessi (<code>truncated</code>). I gruppi colore sono query del linguaggio di ricerca (§2.4) valutate dal backend.</li><li><strong>Tempo di creazione</strong>: proprietà frontmatter <code>created</code> / <code>date created</code> / <code>creation date</code> se valida, altrimenti <code>mtime</code> indicizzato (la data di nascita del file non è disponibile in modo portabile). I nodi fantasma e tag compaiono con la nota meno recente che li collega.</li><li><strong>Impostazioni</strong> in <code>.memobrain/graph.json</code> (aggiunto alla allow-list di <code>ReadConfig</code>/<code>WriteConfig</code>); non scritte sui vault di sola lettura.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>pixi.js (WebGL)</strong> — non necessario per l&#39;obiettivo e con CSP/offline più onerosi; resta l&#39;opzione se in un webview reale i numeri non bastano.</li><li><strong>Birth time dal file system</strong> — dipende dalla piattaforma (Linux spesso assente) e richiederebbe una stat per nota.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><p>Le date del timelapse per note senza <code>created</code> riflettono l&#39;ultima modifica. Il layout non è persistito: ogni apertura riparte da una disposizione nuova (nessun dato derivato da sincronizzare).</p>',10)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
